INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76059, 'spa', 'primero en orden o tiempo', 'Uso dominante que denota la primera posición en una secuencia o un orden temporal — primer día, primer pacto, primer mandamiento. Interlingüísticamente estable: el español ''primero,'' el francés ''premier'' y el alemán ''erster'' convergen en el significado ordinal simple. Abarca prioridad cronológica (Mateo 26:17), clasificación en listas (Mateo 10:2) y la referencia al antiguo pacto como ''primero'' frente al nuevo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76064, 'spa', 'principal, destacado', 'Uso sustantivado que designa a una persona de alto rango social, autoridad o prominencia — un jefe, líder o notable. La fiesta de cumpleaños de Herodes reunió a los ''principales'' de Galilea (Marcos 6:21); los líderes judíos en Tesalónica alistaron a mujeres ''prominentes'' contra Pablo (Hechos 17:4). El desplazamiento de adjetivo ordinal a título de estatus social es claro en los contextos narrativos lucanos y marquinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76072, 'spa', 'primeramente, en primer lugar', 'Empleo adverbial que significa ''en primer lugar'' o ''primeramente,'' indicando prioridad lógica o temporal de una acción. En Antioquía los discípulos fueron llamados ''primeramente'' cristianos (Hechos 11:26); Pablo refiere lo que entregó ''ante todo'' (1 Corintios 15:3). El español ''primeramente'' explicita la fuerza adverbial donde el inglés simplemente reutiliza ''first.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76075, 'spa', 'mejor, de máxima calidad', 'Sentido superlativo cualitativo que significa ''mejor'' o ''más fino,'' no posición secuencial. El caso paradigmático es la orden del padre de traer el ''primer'' (es decir, mejor) vestido para el hijo pródigo (Lucas 15:22). El español recurre a ''mejor,'' revelando que el oyente no entendía ''el primer vestido del perchero,'' sino ''el vestido más fino de la casa'' — un ápice cualitativo, no ordinal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76079, 'spa', 'Primogenito (literal o figurado)', 'El primer hijo nacido en una familia, extendido metaforicamente para denotar prioridad suprema, soberania y preeminencia. El sentido literal aparece en Lucas 2:7 (el primogenito de Maria), mientras que los usos cristologicos dominan: Colosenses 1:15 ''primogenito de toda la creacion'' afirma prioridad sobre el orden creado, y Colosenses 1:18 ''primogenito de entre los muertos'' reclama primacia en la resurreccion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76081, 'spa', 'Tropezar o fallar', 'Tropezar o fallar, usado metafóricamente del fracaso moral y espiritual más que de la caída física. En Rom 11:11, Pablo explora si el «tropiezo» de Israel es definitivo, respondiendo que no: su transgresión trae riqueza a los gentiles. Santiago 2:10 enseña la indivisibilidad de la ley: tropezar en un punto equivale a culpabilidad total. Santiago 3:2 reconoce la fragilidad universal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76084, 'spa', 'Ala protectora', 'El ala de un ave o criatura alada, con fuerza literal y figurada. Los usos evangelicos (Mt 23:37; Lc 13:34) evocan la imagen veterotestamentaria de las alas divinas como refugio (cf. Sal 91:4; Rt 2:12): Jesus se presenta como ave madre que cobija a sus polluelos. En Apocalipsis, las alas senalan la alteridad de los seres celestiales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76093, 'spa', 'Escupir para sanar', 'Describe la acción de Jesús de escupir como parte de sus sanaciones. Marcos 7:33 relata que Jesús escupió y tocó la lengua del sordo. Marcos 8:23 narra que escupió sobre los ojos del ciego y le impuso las manos. Juan 9:6 describe cómo escupió en tierra e hizo lodo con la saliva para dar vista al ciego de nacimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76094, 'spa', 'Cadáver, cuerpo muerto', 'Un cuerpo humano sin vida, un cadáver. La conexión etimológica con πίπτω (caer) se conserva en el sentido literal de ''cuerpo caído'', aunque en el uso neotestamentario el énfasis recae enteramente en la muerte y no en la forma de caer. Todas las traducciones principales convergen en un solo equivalente: español ''cadáver'', francés ''cadavre'', alemán ''Leichnam''. Abarca tanto contextos de sepultura digna como el del cuerpo de Juan el Bautista (Mt 14:12) y escenas de mayor crudeza como los buitres reunidos (Mt 24:28).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76098, 'spa', 'Pobreza material', 'Describe la condición de pobreza material, a veces con significado espiritual. En 2 Corintios 8:2 se elogia a los macedonios cuya profunda pobreza abundó en generosidad. El versículo 9 declara que Cristo, siendo rico, se hizo pobre por nosotros. Apocalipsis usa el término irónicamente para quienes ignoran su verdadera miseria espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76100, 'spa', 'Material y socialmente indigente', 'Material y socialmente indigente: un mendigo o persona reducida a la pobreza extrema, dependiente de la caridad ajena. Jesús anuncia que el evangelio se predica a los pobres como señal mesiánica (Mat 11:5; Luc 4:18). Al joven rico se le ordena dar a los pobres (Mat 19:21), y los pobres están siempre presentes como objeto de compasión (Mat 26:11). El término griego πτωχός connota una necesidad absoluta más intensa que la que suele transmitir la traducción castellana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76104, 'spa', 'Frecuencia de acción', 'Describe acciones que ocurren con frecuencia o de manera repetida. Lucas 5:33 contrasta a los discípulos de Juan que ayunan frecuentemente y hacen oraciones con los de Jesús. Hechos 24:26 señala que Félix mandaba llamar a Pablo con frecuencia esperando un soborno. Primera Timoteo 5:23 aconseja a Timoteo usar un poco de vino por sus frecuentes dolencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76106, 'spa', 'Puerta (entrada de ciudad, templo o recinto)', 'Puerta (entrada de ciudad, templo o recinto). Una puerta grande o portal de una ciudad, templo o fortaleza — el umbral arquitectónico por el que las personas entran y salen. Se usa tanto literalmente para la Puerta Hermosa del templo (Hch 3:10) y la puerta de hierro de una ciudad (Hch 12:10), como metafóricamente para las puertas estrecha y ancha que representan los caminos divergentes de la vida (Mt 7:13–14) y las puertas del Hades que no pueden vencer a la asamblea de Cristo (Mt 16:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76109, 'spa', 'Las puertas monumentales de la Nueva Jerusalén escatológica, que aparecen exclus', 'Las puertas monumentales de la Nueva Jerusalén escatológica, que aparecen exclusivamente en la visión de Juan en Apocalipsis (Ap 21:12-25; 22:14). Cada una de las doce puertas lleva el nombre de una tribu de Israel y está hecha de una sola perla. La evidencia multilingüe es notablemente uniforme -- español puertas, francés porte, alemán Tore -- reflejando la consistencia de la imaginería apocalíptica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76110, 'spa', 'Una entrada o pórtico físico ordinario de una casa, recinto o ciudad en un conte', 'Una entrada o pórtico físico ordinario de una casa, recinto o ciudad en un contexto terrenal. Lázaro yace en el πυλών de la hacienda del hombre rico (Lc 16:20); Rode responde al llamado en el πυλών (Hch 12:13); una criada reconoce a Pedro en el πυλών del patio del sumo sacerdote (Mt 26:71). Este sentido se distingue del escatológico por su carácter cotidiano y doméstico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76113, 'spa', 'Indagar o preguntar con el fin de averiguar hechos, enfatizando el proceso inves', 'Indagar o preguntar con el fin de averiguar hechos, enfatizando el proceso investigativo. Herodes indaga dónde ha de nacer el Mesías (Mt 2:4); el hermano del hijo pródigo pregunta qué sucede (Lc 15:26); el oficial del rey investiga la hora de la curación de su hijo (Jn 4:52). El matiz es de búsqueda activa de información, no mera petición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76120, 'spa', 'Fuego (unidad semantica)', 'Fuego tanto en su sentido literal (fuego de hogar, Marcos 14:54; Lucas 22:55) como en su uso escatologico mucho mas frecuente: juicio divino (Mateo 3:10; 13:42; 25:41), purificacion (1 Corintios 3:13) y destruccion apocaliptica (Apocalipsis 20:14). Todos los idiomas de destino lo traducen con un unico termino para fuego, confirmando su unidad semantica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76128, 'spa', 'Torre fortificada', 'Estructura elevada y fortificada utilizada para defensa, observación o vigilancia agrícola, en particular la torre de piedra erigida en un viñedo o campo. En las parábolas del viñedo (Mt 21:33; Mc 12:1), la torre alude a Isaías 5:2 y simboliza la provisión de Dios. En Lucas, sirve tanto como ilustración de la fragilidad humana como del costo de seguir a Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76130, 'spa', 'Fiebre corporal', 'Fiebre, enfermedad caracterizada por temperatura corporal elevada, etimológicamente vinculada a πῦρ (''fuego''). Cada aparición en el NT se da en contexto de sanación: la suegra de Pedro (Mat 8:15; Mar 1:31; Luc 4:38-39), el hijo del oficial en Capernaúm (Juan 4:52) y el padre de Publio en Malta (Hch 28:8). El término refleja la experiencia universal de la fiebre como calor ardiente interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76136, 'spa', 'Arder de pasión', 'Arder figuradamente con emoción intensa, ya sea deseo sexual o angustia emocional. Pablo aconseja en 1 Cor 7:9 que es mejor casarse que ''quemarse'' (πυροῦσθαι) de pasión descontrolada; en 2 Cor 11:29 pregunta ''¿quién tropieza, y yo no me quemo?'', compartiendo el dolor ajeno como si ardiera por dentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76137, 'spa', 'Refinar con fuego', 'Refinar o purificar mediante el fuego, metáfora metalúrgica de la prueba y purificación divina. En Apoc 1:15, los pies del Cristo glorificado se asemejan a bronce ''refinado'' (πεπυρωμένης) en un horno, y en Apoc 3:18 aconseja comprar oro ''refinado por fuego'' (πεπυρωμένον). La imagen distingue claramente esta acepción de la mera combustión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76140, 'spa', 'Incendiar o estar ardiendo', 'Prender fuego, estar en llamas: combustión física o conflagración escatológica. En Ef 6:16, las flechas del maligno están ''encendidas'' (πεπυρωμένα), son proyectiles en llamas; en 2 Ped 3:12, los cielos ''siendo encendidos'' (πυρούμενοι) se disolverán en el juicio final. Señala la naturaleza literal y física de la acción del fuego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76143, 'spa', 'Rojo como fuego', 'Describe una coloración roja encendida, tanto en un nombre propio como en visiones apocalípticas. En Hechos 20:4 se menciona a «Sópater de Berea, hijo de Πύρρος», nombre que significa «color de llama» o «pelirrojo». En Apocalipsis 6:4 el segundo jinete monta un caballo «rojo como el fuego», y en Apocalipsis 12:3 aparece «un gran dragón rojo encendido con siete cabezas».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76144, 'spa', 'Prueba ardiente', 'Describe la acción de arder o la prueba de fuego, tanto en sentido literal como metafórico. En 1 Pedro 4:12 se habla de «la prueba de fuego que os ha sobrevenido para poneros a prueba». En Apocalipsis 18:9 se describe el juicio sobre Babilonia: los reyes de la tierra «llorarán y se lamentarán cuando vean el humo de su incendio». El término abarca tanto el fuego purificador de la fe como la destrucción por las llamas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76145, 'spa', 'El sentido activo', 'El sentido activo: vender, desprenderse de, u ofrecer bienes y posesiones en venta. El vendedor es el sujeto gramatical, ejerciendo control sobre la transacción. Domina el uso neotestamentario con 19 ocurrencias, abarcando el comercio del templo (Mat 21:12, Mar 11:15, Juan 2:14, 16), la renuncia caritativa (Mat 19:21, Mar 10:21, Luc 18:22), ilustraciones parabólicas (Mat 13:44, 46; Mat 25:9), y la vida comunitaria de la iglesia primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76147, 'spa', 'El sentido pasivo', 'El sentido pasivo: ser vendido, ser puesto en venta, donde la mercancía o los bienes son el sujeto gramatical. Solo tres ocurrencias claras aparecen en el NT, cada una en un contexto distinto. En Mat 10:29, dos pajarillos ''se venden'' por un cuarto; en Luc 12:6, cinco pajarillos ''se venden'' por dos cuartos, ilustrando ambos el cuidado de Dios por lo aparentemente insignificante. En 1 Cor 10:25, Pablo dice a los corintios que coman todo lo que ''se vende'' en la carnicería.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76157, 'spa', 'Un burro joven o pollino, específicamente el animal que Jesús montó en su entrad', 'Un burro joven o pollino, específicamente el animal que Jesús montó en su entrada a Jerusalén cumpliendo Zacarías 9:9. Las doce apariciones en el NT se concentran en los relatos de la entrada triunfal (Mt 21:2, 5, 7; Mr 11:2, 4, 5, 7; Lc 19:30, 33, 35; Jn 12:15). Imagen vívida de realeza humilde montada sobre un animal modesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76160, 'spa', 'Jamás, nunca hasta ahora', 'Adverbio temporal que significa ''alguna vez hasta el presente,'' usado siempre con negación para formar el enfático ''jamás'' o ''nunca.'' En Juan 1:18, nadie ha visto jamás (pōpote) a Dios; en Juan 5:37, nunca han oído la voz del Padre; en Juan 6:35, el creyente jamás tendrá sed; en Juan 8:33, los judíos afirman no haber sido jamás esclavos; y en Luc 19:30, nadie se ha sentado jamás en el pollino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76161, 'spa', 'Endurecimiento espiritual', 'Endurecer o hacer insensible, volver a alguien espiritualmente embotado o ciego. La raiz πῶρος (piedra calcica, callo) confiere al verbo un caracter medico: como el callo que anula la sensacion, el corazon pierde su capacidad de percibir y responder. En Marcos 6:52, los discipulos no comprenden los panes porque su corazon estaba endurecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76162, 'spa', 'Dureza de corazón', 'Describe la dureza o insensibilidad espiritual del corazón. En Marcos 3:5 Jesús mira alrededor «con enojo, entristecido por la dureza de sus corazones» ante la negativa de los fariseos a responder sobre sanar en sábado. Romanos 11:25 habla de «un endurecimiento parcial que ha venido sobre Israel hasta que entre la plenitud de los gentiles». Efesios 4:18 describe a los incrédulos como entenebrecidos en su entendimiento por el endurecimiento de su corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76163, 'spa', '¿cómo? (interrogativo)', 'Uso interrogativo dominante (~103 veces), que introduce preguntas directas e indirectas sobre el modo, el medio o la viabilidad. Las traducciones recurren uniformemente a formas interrogativas directas: español ''cómo,'' francés ''comment,'' alemán ''wie.'' Jesús lo despliega con fuerza retórica: ''¿Cómo puede Satanás expulsar a Satanás?'' (Marcos 3:23), y el asombro de los discípulos aflora en ''¿Cómo entonces puede alguien ser salvo?'' (Mateo 19:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76164, 'spa', 'de algún modo, acaso', 'Adverbio indefinido de aprensión o esperanza cautelosa (~15 veces), que aparece mayormente como μή πως (''no sea que de algún modo'') o expresando ''de alguna manera, quizá.'' El lenguaje de Pablo en Romanos 1:10 (''si de algún modo logro por fin'') y Romanos 11:14 (''si de algún modo provoco a celos'') revela el registro de incertidumbre esperanzada. El español distingue netamente este uso con ''acaso'' y ''de algún modo'' frente al interrogativo directo ''cómo.''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76172, 'spa', 'Título honorífico hebreo que significa ''mi maestro'' o ''mi señor'', usado como for', 'Título honorífico hebreo que significa ''mi maestro'' o ''mi señor'', usado como forma de respeto hacia instructores religiosos judíos. Los discípulos y suplicantes se dirigen a Jesús con este título a lo largo de los Evangelios (Mt 26:25, 49; Mr 9:5; Jn 1:38, 49; 3:2; 6:25). Jesús critica el deseo de los escribas de ser saludados como ''Rabbí'' en público (Mt 23:7) y prohíbe a sus seguidores reclamar el título (Mt 23:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76175, 'spa', 'Palo recto que sirve como bastón de caminante, vara de pastor o cetro real según', 'Palo recto que sirve como bastón de caminante, vara de pastor o cetro real según el contexto. Abarca el bastón del viajero (Mt 10:10; Mr 6:8), el cayado de Jacob al bendecir (He 11:21), el cetro del reino de Cristo (He 1:8) y la vara de hierro del gobierno mesiánico (Ap 2:27; 19:15). Un solo lexema cubre todas estas funciones: pastoral, peregrina y regia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76186, 'spa', 'Aspersión ritual', 'Esparcir un líquido —generalmente sangre o agua— en gotas sobre una persona u objeto con fines de purificación ritual o ratificación de un pacto. El verbo refleja los ritos de aspersión levíticos de la LXX (cf. Lv 14:7; Nm 19:18). En Hebreos 9:13, la aspersión de sangre de macho cabrío y cenizas de becerra santifica «para la purificación de la carne», mientras que en 10:22 el creyente es rociado interiormente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76189, 'spa', 'Bofetada en el rostro', 'Un golpe con la mano, específicamente una bofetada en el rostro, que combina agresión física con ultraje social. En el griego clásico el término abarcaba desde un «golpe» genérico hasta la «bofetada» propiamente dicha e incluso la marca o verdugón resultante. En el Nuevo Testamento las apariciones se concentran en la narrativa de la pasión, donde estos golpes marcan la violencia creciente y el escarnio que Jesús soporta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76199, 'spa', 'Desgarrar, despedazar', 'Desgarrar o despedazar, dicho del ataque violento de un animal. En Mt 7:6, Jesús advierte contra dar lo santo a los perros o echar perlas a los cerdos, ''no sea que os despedacen'' (ῥήξωσιν). El español ''despedacen'' y el francés ''déchirer'' subrayan la ferocidad del ataque. Este sentido extiende la fuerza violenta del verbo desde la ruptura de objetos inanimados al ataque de seres vivos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76200, 'spa', 'Derribar, arrojar al suelo', 'Arrojar o derribar violentamente al suelo, específicamente en el contexto de posesión demoníaca. En Lucas 9:42 el demonio ''lo derribó'' (ἔρρηξεν) y en Marcos 9:18 ''lo derriba'' (ῥήσσει) repetidamente, causando convulsiones. El español ''lo derribó'' y ''lo derriba'' captan el movimiento descendente violento que distingue este sentido del mero reventar de objetos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76201, 'spa', 'Reventar, romper', 'Reventar o romper, dicho de recipientes o barreras que ceden bajo una fuerza interna. Los odres revientan por la fermentación del vino nuevo (Mt 9:17 pasivo; Mr 2:22 y Lc 5:37 activo). En Gál 4:27, Pablo cita Is 54:1: ''¡Prorrumpe y clama!'', redirigiendo la misma energía explosiva hacia la alegría. El español ''romperá'' y ''se rompen'' traducen consistentemente la ruptura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76206, 'spa', 'Palabra, declaracion, dicho', 'Palabra hablada o declaracion concebida como acto comunicativo concreto, enfatizando lo pronunciado mas que el contenido conceptual (cf. λόγος). Se usa para pronunciamientos divinos (''todo ῥῆμα de la boca de Dios'', Mateo 4:4; Lucas 1:37 ''ningun ῥῆμα de Dios sera vacio de poder''), cumplimiento profetico (Mateo 26:75, Pedro ''recordo el ῥῆμα de Jesus'') y habla humana ordinaria (Mateo 12:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76218, 'spa', 'Raiz (literal y figurada)', 'Raiz (literal y figurada): la parte subterranea de una planta de la cual extrae su alimento, extendida figuradamente para significar origen, fuente o causa fundamental. El uso literal aparece en la parabola del sembrador donde la semilla en terreno pedregoso ''no tenia raiz'' (Mt 13:6; Mc 4:6). El uso figurado es prominente: el hacha puesta a la raiz senala juicio (Mt 3:10), la ''raiz de Isai'' apunta al origen mesianico (Ro 15:12), y ''la raiz te sostiene'' advierte a los gentiles sobre su dependencia de Israel (Ro 11:16-18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76225, 'spa', 'Arrojar, lanzar, tirar', 'Arrojar, lanzar o tirar con fuerza, ya sea literalmente al lanzar un objeto o figuradamente al describir a alguien derribado o zarandeado. El verbo abarca desde lanzar objetos (Judas arrojando las monedas, Mt 27:5), derribar personas (el demonio en Lc 4:35), depositar enfermos a los pies de alguien (Mt 15:30), hasta la imagen figurada de multitudes ''esparcidas'' por el agotamiento (Mt 9:36). Las traducciones españolas van de ''arrojaron'' a ''esparcidos'', reflejando la amplitud del verbo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76235, 'spa', 'Espada grande, ῥομφαία', 'Espada grande y ancha —originalmente un arma pesada tracia— usada en el NT tanto para el instrumento literal de muerte (Ap 6:8) como símbolo poderoso de angustia penetrante o autoridad divina. La profecía de Simeón a María emplea el término metafóricamente para el dolor, mientras que en Apocalipsis es la espada de doble filo que sale de la boca de Cristo, representando el juicio y la palabra soberana de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76239, 'spa', 'Callejón urbano', 'Callejuela o calle angosta dentro de un entorno urbano, más pequeña que una vía principal. En Mt 6:2 es el escenario de la limosna ostentosa; en Lc 14:21 el amo ordena a los siervos salir a los callejones para invitar a pobres, lisiados y ciegos. En Hechos designa calles específicas de ciudades como Damasco y Jerusalén, subrayando la precisión geográfica del relato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76240, 'spa', 'Rescatar o librar del peligro', 'Rescatar o librar del peligro: salvar o librar a alguien de enemigos, del mal o de la angustia. Este sentido dominante cubre dieciseis de dieciocho apariciones. Jesus ensena a sus discipulos a orar ''libranos del mal'' (Mt 6:13; Lc 11:4); Pablo relata haber sido rescatado de peligro mortal (2 Co 1:10); las palabras del salmista se citan burlonamente en la cruz: ''que lo libre'' (Mt 27:43).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76244, 'spa', 'Libertador como titulo', 'Libertador como titulo: el participio presente sustantivado ὁ ῥυόμενος usado como titulo mesianico o divino que significa ''el Libertador''. En Romanos 11:26 Pablo cita Isaias 59:20: ''Vendra de Sion el Libertador'', y en 1 Tesalonicenses 1:10 Jesus es ''quien nos libra de la ira venidera''. El termino se capitaliza como titulo propio, marcando el paso del acto verbal a la identidad personal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76257, 'spa', 'Flujo de sangre', 'Describe un flujo crónico de sangre como condición médica. Marcos 5:25 presenta a «una mujer que padecía flujo de sangre desde hacía doce años». Lucas 8:43 repite esta situación, y Lucas 8:44 narra su curación: «tocó el borde de su manto, e inmediatamente su flujo de sangre se detuvo». El término es clínico y directo, subrayando tanto la gravedad médica como las implicaciones de pureza ritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76260, 'spa', 'Ciudadano romano o miembro del orden político romano, aplicado a individuos que ', 'Ciudadano romano o miembro del orden político romano, aplicado a individuos que invocan su ciudadanía legal (Pablo en Hch 16:37; 22:25-29), a entidades políticas colectivas temidas por los líderes judíos (Jn 11:48) y a costumbres legales romanas (Hch 25:16). Una sola designación étnico-política sin diferenciación interna en el NT.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76265, 'spa', 'Roma (nombre propio)', 'La ciudad capital del Imperio Romano, sede del gobierno imperial y lugar de una primitiva comunidad cristiana. Cada aparicion en el NT trata a Roma como ubicacion geografica concreta, no como entidad simbolica (a diferencia de la ''Babilonia'' del Apocalipsis). El viaje de Pablo a Roma constituye el arco narrativo de la segunda mitad de Hechos: el Senor mismo declara ''es necesario que testifiques en Roma'' (Hechos 23:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76272, 'spa', 'Sabado, dia de descanso', 'El sabado, septimo dia consagrado al descanso y la adoracion, central en la practica judia y en las controversias de Jesus con las autoridades religiosas. Tanto σάββατον como σάββατα designan el mismo dia. Los Sinopticos concentran su uso en disputas sobre sanaciones en sabado (Mateo 12:1-12; Marcos 2:23-3:6; Lucas 6:1-11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76276, 'spa', 'Semana, siete dias', 'La semana como periodo de siete dias contado de sabado a sabado, presente en expresiones como ''el primer dia de la semana'' (μία τῶν σαββάτων). Los relatos de la resurreccion emplean uniformemente este sentido (Marcos 16:2; Lucas 24:1; Juan 20:1; Hechos 20:7). El fariseo que declara ''ayuno dos veces a la semana'' (δὶς τοῦ σαββάτου, Lucas 18:12) tambien lo usa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76287, 'spa', 'Miembro de los saduceos, el partido religioso-político judío vinculado a la aris', 'Miembro de los saduceos, el partido religioso-político judío vinculado a la aristocracia sacerdotal y al establecimiento del templo, que rechazaba la creencia en la resurrección, los ángeles y los espíritus (Hch 23:8). Sus confrontaciones con Jesús se centran en la cuestión de la resurrección (Mt 22:23-34; Mr 12:18; Lc 20:27), y en Hechos aparecen como perseguidores de la iglesia primitiva (Hch 4:1; 5:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76292, 'spa', 'Tela de penitencia', 'Tela basta hecha de pelo oscuro de cabra o camello, o prenda confeccionada con dicho tejido, que se vestía para expresar duelo, arrepentimiento o aflicción profunda. Es un préstamo semítico que pasó al griego prácticamente sin alteración. En los Evangelios simboliza el arrepentimiento genuino, y en Apocalipsis funciona como imagen tanto de oscuridad cósmica como de testimonio profético.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76294, 'spa', 'Nombre propio bíblico', 'Identifica a Salatiel en las genealogías de Jesús. Mateo 1:12 traza la línea a través del exilio: ''Después de la deportación a Babilonia, Jeconías engendró a Salatiel, y Salatiel engendró a Zorobabel.'' Lucas 3:27 lo incluye en la genealogía ascendente: ''hijo de Zorobabel, hijo de Salatiel.'' Su presencia constante lo vincula a la historia de restauración de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76297, 'spa', 'Ser sacudido físicamente', 'Ser sacudido físicamente: Sacudimiento físico de objetos, estructuras o cuerpos cósmicos. Este sentido dominante (9 ocurrencias) incluye la sacudida escatológica de las potencias celestiales (Mt 24:29; Mc 13:25; Lc 21:26) y la imagen de una caña mecida por el viento (Mt 11:7; Lc 7:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76301, 'spa', 'Sacudir o agitar activamente', 'Sacudir o agitar activamente: Sacudimiento o agitación activa donde alguien o algo es el agente. Una inundación sacude una casa sin derribarla (Lc 6:48); alborotadores agitan a las multitudes en Tesalónica (Hch 17:13); la voz de Dios sacudirá no solo la tierra sino también el cielo (Heb 12:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76302, 'spa', 'Sacudir para compactar', 'Sacudir para compactar: Sacudir un recipiente para que su contenido se comprima y se asiente. Una única y vívida ocurrencia en Lucas 6:38 donde ''medida buena, apretada, sacudida y rebosante'' describe la generosidad de Dios, transformando el verbo físico en una imagen hogareña de grano compactándose en un recipiente de medida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76303, 'spa', 'Ser perturbado interiormente', 'Ser perturbado interiormente: Perturbación metafórica interior, ser sacudido en la serenidad o las convicciones. David declara ''no seré sacudido'' (Hch 2:25, citando Sal 16:8), y Pablo advierte a los tesalonicenses que no sean ''sacudidos en mente'' por falsos informes sobre el regreso del Señor (2 Ts 2:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76311, 'spa', 'Trompeta (el instrumento o su sonido) — instrumento de viento metálico (o su toq', 'Trompeta (el instrumento o su sonido) — instrumento de viento metálico (o su toque) usado para señalar, adorar y anunciar eventos escatológicos. En los Evangelios, los ángeles reúnen a los elegidos con un gran toque de trompeta (Mt 24:31). Pablo la emplea tanto de forma práctica para la comunicación clara (1 Co 14:8, ''si la trompeta da un sonido incierto'') como escatológicamente para la resurrección (1 Co 15:52, ''la última trompeta''; 1 Ts 4:16, ''la trompeta de Dios''). En Apocalipsis, una voz como de trompeta inicia la revelación (Ap 1:10) y siete trompetas desencadenan los juicios divinos (Ap 8–11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76316, 'spa', 'Tocar la trompeta', 'Tocar la trompeta: Soplar o hacer sonar una trompeta, abarcando las explosiones apocalípticas de juicio (Ap 8:7-13; 9:1; 11:15), la última trompeta escatológica (1 Co 15:52) y el uso figurado de Jesús para la caridad ostentosa (Mt 6:2). Todas las ocurrencias se tratan como una sola acción indivisa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76324, 'spa', 'Samaria (nombre propio, la región/ciudad) — nombre propio de la región (y su ciu', 'Samaria (nombre propio, la región/ciudad) — nombre propio de la región (y su ciudad principal) en el centro de Palestina entre Judea y Galilea, tierra natal de los samaritanos. Teológicamente significativa como la primera zona de expansión del evangelio más allá de Jerusalén: el encuentro de Jesús con la mujer samaritana junto al pozo (Jn 4:4-7), la comisión del Señor resucitado ''en toda Judea y Samaria'' (Hch 1:8), y la misión de Felipe que desató un avivamiento allí (Hch 8:5-14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76326, 'spa', 'Samaritano (gentilicio)', 'Persona de Samaria, la region central de Palestina cuyos habitantes eran considerados por el judaismo oficial como etnica y religiosamente impuros: un gentilicio cargado de significado social y teologico. Jesus subvierte la postura judia convencional: el Buen Samaritano se convierte en modelo de amor al projimo, y la mujer samaritana junto al pozo recibe la revelacion mesianica directamente (Juan 4:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76333, 'spa', 'Profeta y juez', 'Identifica al profeta Samuel en la predicación apostólica y el catálogo de héroes de la fe. Hechos 3:24 afirma que ''todos los profetas desde Samuel en adelante anunciaron estos días''. Hechos 13:20 recuerda la historia de Israel: ''después les dio jueces hasta el profeta Samuel''. Hebreos 11:32 lo incluye entre los héroes de la fe como modelo de fidelidad a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76337, 'spa', 'Saul (nombre propio)', 'El nombre propio Saul, forma helenizada del hebreo sha''ul (''pedido, solicitado''). En el NT designa a dos figuras: el primer rey de Israel, concedido por Dios cuando el pueblo exigio un monarca (Hechos 13:21), y el fariseo de Tarso a quien Jesus resucitado confronta por este mismo nombre en el camino a Damasco (Hechos 9:4, 17; 22:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76338, 'spa', 'Malo, podrido, inutil', 'Podrido, deteriorado, malo o inservible: originalmente referido a la descomposicion fisica (fruta putrefacta, pescado pasado, madera carcomida) y extendido en el NT a la inutilidad moral y cualitativa. Jesus lo emplea en la analogia del arbol y su fruto: ''el arbol malo (sapros) da malos frutos'' (Mateo 7:17-18; 12:33), donde la imagen fisica de la podredumbre se convierte en diagnostico de corrupcion interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76345, 'spa', 'Ciudad e iglesia', 'Identifica la ciudad de Sardis y su iglesia. Apocalipsis 1:11 incluye a Sardis en la lista de las siete ciudades destinatarias del mensaje de Juan. Apocalipsis 3:1 se dirige ''al ángel de la iglesia en Sardis'', advirtiéndole que tiene nombre de estar viva pero está muerta. Apocalipsis 3:4 ofrece esperanza a los pocos fieles que no han manchado sus vestiduras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76349, 'spa', 'Carnal, de la carne', 'Perteneciente a la carne o la naturaleza humana, describiendo lo que se rige por impulsos naturales en vez del Espíritu, o simplemente lo que pertenece al ámbito material. El uso paulino abarca registros tanto negativos como neutros: negativamente, los corintios son «carnales» por andar en celos y contiendas (1 Co 3:3), y Pablo contrasta la sabiduría carnal con la gracia divina (2 Co 1:12); en sentido neutro, designa provisiones materiales como el sustento económico (Ro 15:27; 1 Co 9:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76352, 'spa', 'De carne, carnal', 'Que consiste en carne o se caracteriza por ella; relativo a la dimensión física y mortal de la existencia humana. A diferencia de σαρκικός, que suele connotar un juicio moral negativo (''gobernado por la carne''), σάρκινος enfatiza la composición material. Pablo llama al creyente romano ''carnal, vendido al pecado'' (Rom 7:14) para resaltar la fragilidad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76353, 'spa', 'carne, cuerpo físico', 'La sustancia física del cuerpo humano o animal como un todo organizado, abarcando la carne literal, el cuerpo mortal, la naturaleza humana en su finitud y — sobre todo en Pablo — la orientación no redimida de la vida al margen del Espíritu de Dios (Romanos 8:4-9; Gálatas 5:16-17). A diferencia de σῶμα, σάρξ puede connotar fragilidad moral. El uso encarnacional en Juan 1:14 muestra que el término no es intrínsecamente peyorativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76359, 'spa', 'Barrer, limpiar', 'Describe la acción de barrer, con dimensiones tanto prácticas como espirituales. Mateo 12:44 y Lucas 11:25 presentan la enseñanza del espíritu inmundo que encuentra la casa ''barrida y ordenada'', advirtiendo contra una reforma vacía. Lucas 15:8 relata cómo la mujer que perdió una moneda ''enciende una lámpara, barre la casa y busca con cuidado hasta encontrarla''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76360, 'spa', 'Sara, la matriarca', 'Nombre propio de la esposa de Abraham, la matriarca cuya concepción milagrosa de Isaac encarna la fidelidad de Dios a sus promesas del pacto. Cada referencia neotestamentaria destaca una faceta distinta de su figura: fe en la promesa divina, ejemplo de vida piadosa y símbolo de la gracia que supera las limitaciones humanas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76362, 'spa', 'Nombre propio del adversario espiritual y acusador de la humanidad', 'Nombre propio del adversario espiritual y acusador de la humanidad. Derivado del hebreo ''satan'' (oponente), el Nuevo Testamento lo emplea como nombre propio invariable en todos los casos gramaticales. Jesús se dirige a él directamente durante la tentación (Mat 4:10) y reprende a Pedro con el mismo nombre (Mat 16:23; Mar 8:33). Pablo se refiere a sus maquinaciones (2 Cor 2:11) y a su poder, mientras que Apocalipsis lo identifica como la serpiente antigua (Ap 12:9; 20:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76368, 'spa', 'Saulo (nombre propio)', 'Saulo (nombre propio): Forma grecizada del hebreo שָׁאוּל, que designa al apóstol Pablo por su nombre judío. Usado exclusivamente en Hechos para la identidad pre-conversión de Pablo como perseguidor farisaico (Hch 7:58; 8:1, 3; 9:1) y a lo largo de su experiencia de conversión en el camino a Damasco (Hch 9:4-8, 17). Lucas mantiene este nombre durante el ministerio en Antioquía (Hch 11:25-30; 13:1-2) hasta la transición decisiva en Hechos 13:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76369, 'spa', 'Apagar, extinguir', 'Extinguir, apagar o sofocar fuego o luz, extendido figuradamente a la supresión de la actividad espiritual. El verbo abarca un rango notable: la delicada preservación de una «mecha humeante» (Mt 12:20, citando Is 42:3), la súplica angustiada de las vírgenes insensatas cuyas lámparas «se apagan» (Mt 25:8), y la terrible imagen del fuego inextinguible en la Gehenna (Mr 9:44-48). La metáfora de Pablo «no apaguéis al Espíritu» (1 Ts 5:19) traslada la extinción del plano físico al espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76375, 'spa', 'Pronombre reflexivo de segunda persona singular que marca al destinatario como a', 'Pronombre reflexivo de segunda persona singular que marca al destinatario como agente y paciente a la vez. Aparece en el mandamiento del amor ''como a ti mismo'' (Mat 22:39, citando Lev 19:18), en uso de objeto directo (''sálvate a ti mismo,'' Mat 27:40) e instrucción pastoral (''cuídate a ti mismo,'' 1 Tim 4:16). Su función reflexiva es uniforme en todas las lenguas: español ''a ti mismo'', francés ''toi-même'', alemán ''dich selbst''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76384, 'spa', 'Título imperial romano', 'Describe lo asociado con el emperador romano y su autoridad. Hechos 25:21 informa que Pablo ''apeló para ser custodiado hasta la decisión del Augusto''. Hechos 25:25 continúa el informe de Festo: ''él mismo apeló al Augusto''. Hechos 27:1 menciona la ''Cohorte Augusta''. Se trata de vocabulario técnico imperial conservado en su forma griega en todas las lenguas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76385, 'spa', 'Adorar, venerar a Dios — adorar o venerar a Dios con devoción piadosa, usado tan', 'Adorar, venerar a Dios — adorar o venerar a Dios con devoción piadosa, usado tanto para la veneración religiosa sincera como para la adoración vana y meramente de labios. En Hechos, identifica de modo característico a los gentiles temerosos de Dios (σεβόμενοι) que se sentían atraídos por el monoteísmo y la ética del judaísmo sin conversión plena: Lidia (Hch 16:14), los griegos devotos en Tesalónica (Hch 17:4) y los asistentes cercanos a los prosélitos en las sinagogas (Hch 13:43, 50). En los Evangelios, Jesús cita a Isaías contra la adoración hipócrita (Mt 15:9; Mr 7:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76392, 'spa', 'Terremoto', 'Terremoto: Sacudida de la tierra, un terremoto — el sentido primario y abrumadoramente dominante en el Nuevo Testamento. Aparece en advertencias apocalípticas (Mt 24:7; Mc 13:8; Lc 21:11; Ap 6:12; 8:5; 11:13, 19; 16:18) y en momentos narrativos de intervención divina (Mt 27:54; 28:2). La evidencia interlingüística es notablemente uniforme: español ''terremoto'', francés ''tremblement de terre'', alemán ''Erdbeben''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76394, 'spa', 'Tempestad violenta', 'Tempestad violenta: Sacudida violenta del mar, una tormenta o tempestad. En Mt 8:24, σεισμὸς μέγας describe la tormenta repentina en el mar de Galilea mientras Jesús duerme en la barca. La palabra extiende la imagen central de sacudimiento de la tierra al agua, captando la fuerza convulsiva de la tormenta. Varias traducciones lo vierten como ''terremoto'' o ''temblor'', pasando por alto el contexto marítimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76395, 'spa', 'Sacudir o estremecer', 'Sacudir, hacer temblar o agitar, aplicado a terremotos, conmocion emocional y cataclismos cosmicos. El termino tiene enorme peso dramatico en Mateo: la tierra tiembla a la muerte de Jesus (27:51), los guardias se estremecen de terror ante su resurreccion (28:4), y toda la ciudad se conmueve en su entrada triunfal (21:10). Hebreos 12:26 escala hacia la sacudida escatologica final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76398, 'spa', 'Luna', 'La luna como cuerpo celeste. Las nueve apariciones neotestamentarias señalan al objeto lunar físico, típicamente en pasajes que describen señales cósmicas o el ordenamiento de las luminarias celestiales. Jesús advierte que la luna se oscurecerá (Mt 24:29; Mr 13:24), Lucas registra angustia cósmica que involucra a la luna (Lc 21:25), Pedro cita la profecía de Joel sobre la luna convertida en sangre (Hch 2:20), y Pablo distingue la gloria propia de la luna entre los astros (1 Co 15:41).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76403, 'spa', 'Digno, honorable', 'Digno de respeto, decoroso, honorable. Describe un carácter o una conducta que inspira admiración reverente — no una gravedad pomposa, sino un peso moral genuino. Se usa para la conducta personal en las Epístolas Pastorales (1 Ti 3:8, 11; Tit 2:2) y para aquello que merece contemplación (Fil 4:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76404, 'spa', 'Dignidad decorosa', 'Describe el comportamiento digno y respetable que se espera de los creyentes, especialmente de los líderes. Primera Timoteo 2:2 ora por una vida tranquila «en toda piedad y dignidad». Primera Timoteo 3:4 exige que el obispo gobierne su casa «con toda dignidad». Tito 2:7 instruye a mostrar «integridad, dignidad» en la enseñanza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76408, 'spa', 'Significar o indicar', 'Significar o dar a conocer mediante señales, indicando algo a través de comunicación indirecta, simbólica o profética en vez de lenguaje llano. En Juan 12:33 y 18:32, Jesús señala qué tipo de muerte habría de sufrir; en Juan 21:19, señala el futuro martirio de Pedro; en Hch 11:28, Ágabo señala una hambruna por el Espíritu; en Hch 25:27, Festo debe indicar los cargos; y en Apoc 1:1, Dios da a conocer la revelación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76412, 'spa', 'Senal milagrosa', 'Senal milagrosa o signo autenticador que apunta a la autoridad divina. En los Sinopticos, los adversarios exigen un σημεῖον como prueba (Mateo 12:38-39), mientras que Juan se organiza en torno a siete senales que revelan la gloria de Jesus. Pablo apela a ''senales y prodigios'' como credenciales apostolicas (2 Corintios 12:12). El discurso escatologico advierte sobre senales enganosas (Mateo 24:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76416, 'spa', 'Adverbio que designa el día presente, usado tanto en referencia temporal ordinar', 'Adverbio que designa el día presente, usado tanto en referencia temporal ordinaria como en declaraciones teológicamente cargadas de acción divina en el momento actual. Los dichos sinópticos lo emplean para la providencia diaria (''basta a cada día su propio mal,'' Mat 6:34) y para anuncios escatológicos (''hoy estarás conmigo en el paraíso,'' Luc 23:43). Hebreos lo extiende a una teología de la exhortación, citando el Salmo 95:7 (''hoy, si oís su voz'') como ventana perpetuamente abierta de gracia (Heb 3:7–4:7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76419, 'spa', 'Agente de deterioro', 'Se refiere a las polillas como agentes de deterioro y pérdida material. Mateo 6:19-20 contrasta los tesoros: «No acumuléis tesoros en la tierra, donde la polilla y el óxido destruyen». Lucas 12:33 repite esta enseñanza: «Haceos bolsas que no se envejezcan, tesoro en los cielos que no se agote». La polilla simboliza la fragilidad de las posesiones terrenales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76423, 'spa', 'Callar, guardar silencio — estar en silencio, guardar la paz o cesar de hablar', 'Callar, guardar silencio — estar en silencio, guardar la paz o cesar de hablar: abstenerse de pronunciar palabra, ya sea de forma voluntaria o por mandato. Lucas emplea este verbo con especial frecuencia: los discípulos ''callaron'' tras la Transfiguración (Lc 9:36), la multitud intentó silenciar al mendigo ciego (Lc 18:39) y los saduceos, asombrados por la respuesta de Jesús, ''enmudecieron'' (Lc 20:26). En Hechos, Pedro hace señal de silencio antes de relatar su liberación milagrosa (Hch 12:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76425, 'spa', 'Mantener en secreto, ocultar — guardar algo en secreto, ocultar una verdad en si', 'Mantener en secreto, ocultar — guardar algo en secreto, ocultar una verdad en silencio durante un período prolongado. En Ro 16:25 el ''misterio guardado en silencio (σεσιγημένου) por largos siglos'' ha sido ahora revelado; aquí σιγάω trasciende el simple callar conversacional para describir la retención divina de la revelación a través de las eras. El silencio se convierte en ocultamiento cósmico que finalmente es quebrantado por la proclamación del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76432, 'spa', 'Hecho de hierro', 'Compuesto de o hecho de hierro, describe objetos fisicos (puertas, varas, corazas) con la connotacion de extrema dureza e indestructibilidad. Las cinco ocurrencias neotestamentarias portan este sentido: la puerta de hierro en Hechos 12:10 y las varas o corazas de hierro en Apocalipsis. Cuando se aplica al cetro mesianico, el hierro evoca una autoridad irresistible e inapelable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76434, 'spa', 'Sidón (nombre propio geográfico) — nombre propio geográfico de la antigua ciudad', 'Sidón (nombre propio geográfico) — nombre propio geográfico de la antigua ciudad costera fenicia (la moderna Saida, Líbano), emparejada consistentemente con Tiro en la tradición bíblica. Jesús usa Sidón como contraste para las ciudades galileas impenitentes (Mt 11:21-22; Lc 10:13-14), visita su región (Mt 15:21; Mr 7:31) y atrae multitudes de allí (Mr 3:8; Lc 6:17). Pablo visita Sidón en su camino a Roma (Hch 27:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76439, 'spa', 'Silas (nombre propio)', 'Silas (nombre propio): Nombre propio que designa a un profeta y líder judío cristiano de la iglesia de Jerusalén que acompañó a Pablo en su segundo viaje misionero. Conocido también por la forma romanizada Silvano (Σιλουανός) en las Epístolas. Las 13 ocurrencias en Hechos se refieren a este único individuo, abarcando su comisión por el Concilio de Jerusalén (Hch 15:22, 27, 32) y sus viajes por Asia Menor y Grecia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76440, 'spa', 'Silvano, nombre propio', 'Silvano, nombre propio. Forma latinizada de Silas, referida a un destacado líder cristiano primitivo que sirvió como colaborador de Pablo y coautor de cartas. Predicó junto a Pablo y Timoteo en Corinto (2 Cor 1:19), participó en la redacción de la correspondencia tesalonicense (1 Ts 1:1; 2 Ts 1:1) y entregó o coescribió 1 Pedro (1 Pe 5:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76441, 'spa', 'Estanque de Siloé', 'Identifica el estanque de Siloé en Jerusalén. Lucas 13:4 menciona una tragedia: «aquellos dieciocho sobre los cuales cayó la torre en Siloé». Juan 9:7 registra la instrucción de Jesús al ciego: «Ve a lavarte en el estanque de Siloé (que significa Enviado)». Juan 9:11 repite el relato. La identificación constante en todas las lenguas confirma que es un topónimo específico y reconocido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76443, 'spa', 'Simon (nombre propio)', 'Nombre propio griego Σίμων (del hebreo שִׁמְעוֹן, ''el ha oido''), aplicado a multiples personajes del NT, sobre todo Simon Pedro (Mateo 4:18; 16:16), pero tambien Simon el Zelote, Simon de Cirene, Simon el leproso, Simon el curtidor y Simon el Mago. Todos los idiomas lo transliteran directamente, dependiendo del contexto narrativo para distinguir a cada portador.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76447, 'spa', 'Sinaí, el monte', 'Sinaí, el monte en el desierto donde Dios reveló la Ley a Moisés. Del hebreo סִינַי. En Hechos 7:30 es el sitio de la teofanía de la zarza ardiente, y en Hechos 7:38 el lugar de la entrega de la Ley. Pablo lo usa alegóricamente en Gálatas 4:24-25 como figura del antiguo pacto de esclavitud, contrastándolo con la libertad del nuevo pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76448, 'spa', 'Planta de mostaza', 'La planta de mostaza (genero Sinapis), referida exclusivamente en genitivo ("de mostaza") para describir su semilla proverbialmente diminuta. Las cinco ocurrencias se agrupan en dos contextos de ensenanza: la parabola del reino (Mt 13:31; Mr 4:31; Lc 13:19) y el dicho sobre la fe como grano de mostaza (Mt 17:20; Lc 17:6). Un unico referente botanico con inmensa carga simbolica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76449, 'spa', 'Lienzo, sábana de lino', 'Pieza de tela de lino que se lleva holgadamente sobre el cuerpo como vestidura o envoltura sencilla. En Mark 14:51-52, el joven en Getsemaní solo lleva una σινδών echada sobre su cuerpo desnudo; al ser sujetado, la abandona y huye. La misma palabra aparece en Mark 15:46 para la tela que José compra, antes de convertirse en mortaja.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76450, 'spa', 'Mortaja de lino', 'Tela de lino fino usada específicamente como mortaja funeraria para envolver un cadáver antes de la sepultura. En Matt 27:59 y Luke 23:53, σινδών designa el lino limpio en que el cuerpo de Jesús fue reverentemente envuelto. Aunque materialmente idéntico al sentido 1, el contexto funerario confiere a este uso una solemnidad distintiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76453, 'spa', 'Becerro engordado', 'Describe al becerro engordado en la parábola del hijo pródigo. Lucas 15:23 recoge la orden del padre: «Traed el becerro gordo y matadlo, y comamos y hagamos fiesta». El versículo 27 relata la explicación del siervo al hermano mayor. El versículo 30 cita la queja del hermano mayor. El término transmite generosidad, celebración y la alegría del reencuentro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76456, 'spa', 'Trigo', 'Trigo: Trigo específicamente — el grano cultivado Triticum, ya sea en pie en el campo, siendo cosechado o almacenado. Central en las parábolas de Jesús: el trigo y la cizaña (Mt 13:25-30) donde el trigo representa a los justos, y el grano de trigo que debe morir para dar fruto (Jn 12:24). También aparece en contextos comerciales (Ap 6:6; 18:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76458, 'spa', 'Grano, provisiones', 'Grano, provisiones: Grano o cereal en un sentido más amplio y genérico — provisiones alimentarias o suministros almacenados más que trigo como cultivo específico. En Lc 12:18, el rico insensato planea almacenar su ''grano'' (toda su cosecha), y en Hch 7:12, Jacob oye que hay ''grano'' en Egipto. El énfasis contextual en el aprovisionamiento más que en el cultivo distingue este sentido del anterior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76459, 'spa', 'Sion (nombre propio)', 'El nombre propio Sion, que designa el monte santo y la ciudad de Jerusalén, usado tanto como referencia geográfica literal como rico símbolo teológico de la presencia de Dios entre su pueblo. En los Evangelios, «hija de Sion» (Mt 21:5; Jn 12:15) evoca la poesía profética sobre Jerusalén y su rey venidero. Pablo lo aplica a la profecía mesiánica de la piedra angular (Ro 9:33) y a la liberación escatológica de Israel (Ro 11:26), mientras que Hebreos 12:22 y Apocalipsis 14:1 lo elevan a la Sion celestial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76461, 'spa', 'Callar, guardar silencio, cesar de hablar o de hacer ruido', 'Callar, guardar silencio, cesar de hablar o de hacer ruido. Se aplica a personas a quienes se ordena callar (Mt 20:31; Mr 10:48; Lc 18:39), al silencio deliberado de Jesús ante sus acusadores (Mt 26:63) y a la naturaleza cuando Jesús manda a la tormenta que se aquiete (Mr 4:39). También se usa para abstenerse de hablar, como cuando se le dice a Pablo que no calle (Hch 18:9). El español ''callar'' y el francés ''se taire'' reflejan ambas dimensiones de este silencio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76470, 'spa', 'El sentido causativo activo', 'El sentido causativo activo: poner un tropiezo ante alguien, llevándolo al pecado o a la ruina espiritual. Jesús lo usa con fuerza en el Sermón del Monte: ''si tu ojo derecho te hace tropezar, arráncalo'' (Mat 5:29), y en su severa advertencia sobre las piedras de molino para quienes hacen tropezar a los pequeños (Mat 18:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76472, 'spa', 'El sentido pasivo o medio', 'El sentido pasivo o medio: escandalizarse, ofenderse o sentir indignación contra alguien. Cuando Jesús dice ''bienaventurado el que no se escandaliza de mí'' (Mat 11:6), la palabra describe una reacción interior de indignación o rechazo. Los de Nazaret ''se escandalizaban de él'' (Mat 13:57), incapaces de ver más allá del hijo del carpintero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76473, 'spa', 'Un sentido pasivo intensificado que denota apostasía o abandono espiritual bajo ', 'Un sentido pasivo intensificado que denota apostasía o abandono espiritual bajo la prueba. Jesús profetiza ''todos seréis escandalizados'' la víspera de su crucifixión (Mat 26:31, citando Zac 13:7), y advierte que ''muchos serán escandalizados'' en el discurso escatológico (Mat 24:10). Aquí el tropiezo no es una ofensa momentánea, sino un colapso de la lealtad, una dispersión del rebaño bajo la persecución.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76489, 'spa', 'Tropiezo, causa de ofensa', 'Tropiezo, causa de ofensa: Gatillo de trampa, lazo u obstáculo que causa que alguien caiga en pecado o ruina espiritual. El NT lo emplea exclusivamente en sentidos metafóricos: causas de pecado recogidas en el juicio (Mt 13:41), Pedro como tropiezo para la misión de Jesús (Mt 16:23), y la triple advertencia de Mt 18:7. El español ''escándalo'' desciende directamente de esta palabra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76493, 'spa', 'Excavar la tierra', 'Describe la acción de cavar en contextos tanto prácticos como parabólicos. Lucas 6:48 compara al constructor prudente con quien «cavó y ahondó y puso el cimiento sobre la roca». Lucas 13:8 recoge la súplica del viñador por la higuera estéril: «déjala todavía este año, hasta que yo cave alrededor y la abone». Lucas 16:3 cita al administrador injusto: «cavar, no puedo».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76494, 'spa', 'Bote del navío', 'Se refiere al bote auxiliar durante el viaje y naufragio de Pablo. Hechos 27:16 describe cómo, al resguardarse de una isla, lograron con dificultad asegurar el esquife. Hechos 27:30 relata el intento de los marineros de huir arriando el bote al mar, y Hechos 27:32 narra cómo los soldados cortaron las amarras del bote por intervención de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76495, 'spa', 'Piernas de crucificados', 'Se refiere a las piernas de los crucificados junto a Jesús. Juan 19:31 presenta la petición de los judíos a Pilato de que les quebraran las piernas. El versículo 32 relata que los soldados quebraron las piernas de los otros dos, y el versículo 33 ofrece el detalle crucial: al llegar a Jesús y verlo ya muerto, no le quebraron las piernas, cumpliendo así la Escritura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76499, 'spa', 'Vasija, jarro, recipiente o instrumento, tanto literal como metafórico', 'Vasija, jarro, recipiente o instrumento, tanto literal como metafórico. Este sentido dominante (19 ocurrencias) abarca recipientes físicos como la vasija en la cruz (Juan 19:29), la lámpara que se coloca sobre un candelero y no debajo de una vasija (Luc 8:16), y el recipiente en forma de lienzo en la visión de Pedro (Hch 10:11). Figuradamente, Pablo es un ''vaso escogido'' (Hch 9:15) y los seres humanos son vasos de misericordia o de ira (Rom 9:22-23).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76501, 'spa', 'Bienes domésticos, posesiones o propiedad personal en plural colectivo', 'Bienes domésticos, posesiones o propiedad personal en plural colectivo. La parábola de Jesús sobre atar al hombre fuerte gira en torno a este sentido: primero hay que atarlo antes de saquear sus ''bienes'' (Mat 12:29, Mar 3:27). En Lucas 17:31, el que esté en la azotea no debe bajar a recoger sus ''pertenencias''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76504, 'spa', 'Equipo náutico, jarcia o aparejo de un barco', 'Equipo náutico, jarcia o aparejo de un barco: un sentido técnico especializado atestiguado una sola vez en Hechos 27:17. Durante la violenta tormenta mediterránea, los marineros ''arriaron el aparejo'', refiriéndose al velamen o la jarcia. El singular σκεῦος aquí sigue el uso marítimo del griego clásico donde designaba el equipamiento de un navío.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76505, 'spa', 'Tabernaculo, tienda sagrada', 'Tabernaculo, tienda sagrada: el tabernaculo sagrado, el santuario portatil en forma de tienda de Israel y su arquetipo celestial. Hebreos usa σκηνή extensamente tanto para el tabernaculo mosaico como para la ''tienda verdadera'' levantada por el Senor (He 8:2; 9:2-3, 11, 21). Hechos 7:43-44 recuerda el tabernaculo del desierto, y Hechos 15:16 cita a Amos sobre la reconstruccion de la tienda caida de David.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76507, 'spa', 'Tienda, refugio temporal', 'Tienda, refugio temporal: una tienda ordinaria o enramada temporal para refugio humano. En la Transfiguracion, Pedro propone hacer tres tiendas para Jesus, Moises y Elias (Mt 17:4; Mc 9:5; Lc 9:33), refugios fisicos que evocan la Fiesta de los Tabernaculos. Hebreos 11:9 describe a Abraham habitando en tiendas como peregrino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76509, 'spa', 'Morada, habitacion', 'Morada, habitacion: una morada metaforica o habitacion permanente que extiende la imagen de la tienda mas alla de lo temporal. En Lucas 16:9, Jesus habla de ser recibido en ''tiendas eternas'' (αἰωνίους σκηνάς), una paradoja llamativa: las tiendas son por naturaleza temporales, pero estas son eternas. El espanol traduce esto como ''moradas'', abandonando la imagen de tienda por completo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76513, 'spa', 'Habitar, tabernacular', 'Morar, establecer residencia o tabernacular, con la idea raíz de plantar una tienda (σκηνή). Los cinco usos neotestamentarios portan peso teológico: Juan 1:14 anuncia al Verbo encarnado ''tabernaculando'' entre la humanidad, evocando la presencia de Dios en la tienda de reunión del desierto. En Apocalipsis, Dios cobija (σκηνόω) a su pueblo (Ap 7:15; 21:3), mientras que Ap 12:12 y 13:6 se refieren a quienes habitan en el cielo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76514, 'spa', 'Morada o tabernáculo', 'Describe lugares de habitación con significado tanto literal como metafórico. Hechos 7:46 evoca el deseo de David de hallar morada para el Dios de Jacob. Segunda de Pedro 1:13-14 lo usa metafóricamente para el cuerpo: Pedro considera justo avivar a los creyentes mientras habita en esta tienda, sabiendo que pronto la dejará. La evidencia interlingüística muestra convergencia en términos de habitación y tabernáculo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76515, 'spa', 'Sombra', 'Sombra en sus dimensiones tanto física como metafórica. Físicamente, denota la penumbra proyectada por un objeto —aves refugiándose a la sombra de las ramas (Mc 4:32) o la sombra de Pedro cayendo sobre los enfermos (Hch 5:15). Figuradamente, designa la profunda oscuridad de la muerte y la ignorancia espiritual que la luz mesiánica disipa (Mt 4:16; Lc 1:79). Teológicamente, describe los ritos veterotestamentarios como anticipos imperfectos de las realidades plenas reveladas en Cristo (Col 2:17; Heb 8:5; 10:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76517, 'spa', 'Saltar de gozo', 'Todas las lenguas de destino convergen en un sentido claro: un movimiento repentino y gozoso de saltar o brincar. Lucas lo emplea tanto en sentido literal, para el movimiento del niño en el vientre materno, como en sentido figurado, para la exultación de los creyentes bajo persecución. El término connota una alegría tan intensa que se desborda en expresión corporal espontánea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76518, 'spa', 'Dureza de corazón', 'Todas las lenguas conservan la estructura compuesta: español ''dureza de corazón'', francés ''dureté de cœur'', alemán ''Herzenshärte''. Esta unanimidad revela un término técnico para una condición espiritual específica. El mundo antiguo situaba la capacidad de respuesta moral en el corazón, órgano que podía petrificarse y perder su facultad de recibir la verdad divina y obedecer.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76519, 'spa', 'Duro, áspero, severo', 'Duro, áspero, severo o inflexible, aplicado tanto a personas como a cosas difíciles de soportar o aceptar. El «amo duro» de la parábola (Matt 25:24) describe un carácter exigente y despiadado; la «palabra dura» de John 6:60 resulta intelectual y espiritualmente intolerable para los discípulos; los «aguijones» de Acts 9:5 y 26:14 son instrumentos agudos e implacables; el viento «recio» de James 3:4 es violento e indomable.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76526, 'spa', 'Endurecer, hacer obstinado', 'Endurecer o hacer obstinado en sentido activo: el acto deliberado de causar que un corazón se vuelva inflexible ante la voz o la verdad de Dios. En Heb 3:8, 3:15 y 4:7 aparece como advertencia en subjuntivo tomada del Salmo 95: «No endurezcáis vuestros corazones como en la provocación.» Rom 9:18 atribuye el endurecimiento a la agencia divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76527, 'spa', 'Endurecerse, volverse obstinado', 'Endurecerse o volverse obstinado, usado en voz pasiva o media para describir el estado resultante de rigidez espiritual. En Acts 19:9, el tiempo imperfecto (ἐσκληρύνοντο) capta un proceso progresivo: algunos se iban endureciendo contra el Camino. Heb 3:13 advierte contra ser endurecido por el engaño del pecado, donde la voz pasiva sugiere que el endurecimiento sobreviene gradualmente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76530, 'spa', 'Torcido o perverso', 'Torcido, encorvado; por extensión, moralmente perverso o corrupto. El sentido literal de curvatura física (opuesto a εὐθύς, ''recto'') sustenta el uso metafórico dominante en el NT. En Lucas 3:5 se refiere a lo que será enderezado con la venida del Señor; en Hechos 2:40 y Filipenses 2:15 describe una generación moralmente desviada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76532, 'spa', 'Considerar, prestar atención', 'Mirar con atención, considerar o fijar la mente en algo con cuidado. En 2 Cor 4:18, Pablo usa el participio σκοπούντων para los creyentes que ponen su mirada en las realidades eternas e invisibles. Phil 2:4 exhorta a cada uno a considerar (σκοποῦντες) los intereses de los demás, no solo los propios. Gal 6:1 llama al espiritual a examinarse a sí mismo (σκοπῶν σεαυτόν) para no caer también en tentación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76533, 'spa', 'Vigilar, estar en guardia', 'Vigilar, estar en guardia o mantener un ojo atento sobre alguien o algo que representa una amenaza. En Rom 16:17, Pablo ordena a los creyentes que vigilen (σκοπεῖν) a quienes causan divisiones contrarias a la sana doctrina. Phil 3:17 invierte la valencia: «Observad (σκοπεῖτε) a los que andan conforme al modelo que os dimos», donde la vigilancia es positiva e invita a la imitación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76538, 'spa', 'Esparcir, dispersar', 'Esparcir, dispersar o separar por la fuerza, describiendo tanto la disgregación violenta de un grupo como la distribución amplia de algo. Los usos neotestamentarios abarcan desde la dispersión negativa (el lobo dispersa ovejas, Jn 10:12; discípulos dispersados, Jn 16:32; quien no recoge, esparce, Mt 12:30/Lc 11:23) hasta la distribución positiva de generosidad a los pobres (2 Co 9:9 citando Sal 112:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76539, 'spa', 'Escorpión', 'Escorpión, arácnido venenoso del orden Scorpiones, empleado tanto literalmente como en calidad de potente símbolo de peligro y daño demoníaco. Lucas 10:19 empareja escorpiones con serpientes como representantes de fuerzas espirituales hostiles sobre las cuales Jesús otorga autoridad. Lucas 11:12 usa el escorpión en una analogía doméstica sobre el cuidado paternal. Apocalipsis 9:3, 5, 10 retrata criaturas apocalípticas con poder semejante al del escorpión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76540, 'spa', 'Oscuro, tenebroso', 'La evidencia multilingüe converge en oscuridad: español «oscuro», francés «ténébreux», inglés «dark». Los tres usos neotestamentarios aparecen en la enseñanza de Jesús sobre el ojo, donde «oscuro» contrasta con «sano» o «íntegro», indicando que la percepción espiritual puede nublarse y sumergir todo el mundo interior en tinieblas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76541, 'spa', 'Oscuridad, tiniebla', 'Oscuridad, tiniebla: oscuridad entendida tanto como penumbra fisica como condicion espiritual y moral opuesta a la luz y la verdad divinas. En los Sinopticos describe el ambito de quienes aun no han recibido la revelacion: ''el pueblo sentado en tinieblas ha visto una gran luz'' (Mt 4:16). En la teologia de Juan se convierte en metafora central de la alienacion de Dios: ''la luz resplandece en las tinieblas'' (Jn 1:5), y quienes permanecen en ella rechazan la revelacion divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76542, 'spa', 'Oscurecer, entenebrecer', 'Oscurecer o ser entenebrecido, abarcando tanto la privación literal de luz celestial como el enceguecimiento metafórico del entendimiento humano. El uso cósmico aparece en la apocalíptica sinóptica (Mt 24:29; Mc 13:24) y el juicio de la trompeta de Ap 8:12, donde sol, luna y estrellas pierden su resplandor, evocando Joel 2:31 e Isaías 13:10. El uso espiritual en Romanos describe mentes y corazones sumidos en tinieblas por rechazar la revelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76543, 'spa', 'Oscuridad como ausencia u opuesto de la luz, abarcando registros físicos, morale', 'Oscuridad como ausencia u opuesto de la luz, abarcando registros físicos, morales y escatológicos. Literalmente, marca las tinieblas de la crucifixión sobre la tierra (Mat 27:45, Mar 15:33). Como metáfora de la ceguera espiritual, se opone a la luz de Dios y de Cristo (Juan 1:5, Hch 26:18, Col 1:13). Las ''tinieblas de afuera'' (Mat 8:12, 22:13, 25:30) representan la exclusión final de la presencia de Dios. Pablo usa el contraste luz-tinieblas para definir la identidad cristiana (1 Tes 5:4-5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76546, 'spa', 'Oscurecer, entenebrecer', 'Las lenguas romances usan términos de la familia «oscurecer/entenebrecer» (español «oscurecido», francés «obscurcir»), mientras que el alemán emplea «verfinstern». Las formas de participio pasivo predominan, indicando algo que recibe la acción: mentes entenebrecidas por el pecado, cielos oscurecidos por el juicio divino. En Apocalipsis se presenta como castigo cósmico; en Efesios, como condición espiritual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76550, 'spa', 'Molestar o acosar', 'Molestar, importunar, acosar o fatigar. Originalmente ''desollar o desgarrar'', el término se suavizó en el koiné hasta expresar la idea de causar cansancio o perturbación. En Mateo 9:36 la voz pasiva describe a las multitudes ''acosadas'' como ovejas sin pastor. En Marcos 5:35 y Lucas 8:49 significa imponer innecesariamente una carga sobre Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76553, 'spa', 'Gusano, larva', 'Las traducciones son uniformes en todas las lenguas: español «gusano», francés «ver», alemán «Wurm». Esta unanimidad refleja un término concreto y sin ambigüedad. La triple repetición de Jesús (Mc 9:44, 46, 48) subraya el horror del juicio final mediante esta imagen visceral: gusanos que roen incesantemente a los muertos, emblema de descomposición y perdición perpetuas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76559, 'spa', 'Nombre propio de la antigua ciudad de la llanura del Jordán destruida por fuego ', 'Nombre propio de la antigua ciudad de la llanura del Jordán destruida por fuego divino (Gn 19), que funciona en el Nuevo Testamento como el ejemplo paradigmático de juicio catastrófico sobre la maldad. Jesús la usa para avergonzar a las ciudades galileas que no responden (Mt 10:15; 11:23-24), Pablo cita la profecía de Isaías sobre Sodoma respecto al remanente de Israel (Ro 9:29), y Pedro y Judas citan su destrucción como advertencia para los impíos (2 P 2:6; Jud 7). Apocalipsis aplica el nombre simbólicamente a Jerusalén (Ap 11:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76562, 'spa', 'Salomón (nombre propio)', 'Salomón (nombre propio): Nombre propio del hijo de David y sabio rey de Israel, invocado en la genealogía del NT (Mt 1:6), en comparaciones con la mayor sabiduría y gloria de Jesús (Mt 6:29; 12:42; Lc 11:31), y en el topónimo ''Pórtico de Salomón'' (Jn 10:23; Hch 3:11). Todos los idiomas transliteran este único referente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76566, 'spa', 'tu, tuyo (posesivo) — Posesivo de segunda persona singular (''tu, tuyo/a''), emple', 'tu, tuyo (posesivo) — Posesivo de segunda persona singular (''tu, tuyo/a''), empleado en el discurso directo para señalar lo que pertenece al interlocutor. Jesús lo utiliza en desafíos personales incisivos: ''la viga en tu ojo'' (Mt 7:3), ''tu fe te ha salvado'', y en momentos de profunda intimidad teológica: ''no mi voluntad sino la tuya'' (Lc 22:42), ''lo tuyo es mío y lo mío es tuyo'' (Jn 17:10). En las parábolas marca posesión y rendición de cuentas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76578, 'spa', 'Sudario o pañuelo', 'Paño o lienzo, originalmente para enjugar el sudor (del latín sudarium). Se usaba como sudario para envolver el rostro en la sepultura (Juan 11:44; 20:7), como envoltura de objetos de valor (Lucas 19:20), y como paños llevados desde el cuerpo de Pablo para sanación (Hechos 19:12). El español ''sudario'' conserva la asociación funeraria del latín.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76580, 'spa', 'Sabiduria', 'Sabiduria como cualidad integral que abarca discernimiento divino, prudencia practica y comprension moral. En los Sinopticos designa la autoridad docente de Jesus (Mateo 13:54; Marcos 6:2) y la sabiduria de Salomon (Mateo 12:42). En Pablo, σοφία se redefine radicalmente: la sabiduria del mundo es necedad ante Dios, y Cristo crucificado es ''la sabiduria de Dios'' (1 Corintios 1:24, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76583, 'spa', 'Sabio, habil en juicio', 'Sabio, habil en juicio: sabio o que posee sabiduria y discernimiento, usado tanto positivamente de la comprension genuina como ironicamente de la astucia autopercibida. Jesus oculta la verdad a ''los sabios'' en una inversion de expectativas (Mt 11:25; Lc 10:21), mientras Pablo cuestiona la sabiduria mundana (1 Co 1:20; Ro 1:22) pero tambien elogia al sabio constructor (1 Co 3:10). El sustantivo plural ''sabios'' aparece en Mt 23:34.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76588, 'spa', 'Convulsionar, desgarrar', 'El español emplea «convulsionar» de forma consistente, mientras que el francés «déchirer» (desgarrar) preserva el sentido violento original. Los relatos de exorcismo muestran esto como un acto desesperado y final: el demonio convulsiona a su víctima una última vez antes de ser expulsado, manifestando tanto su malicia como su impotencia ante la autoridad de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76592, 'spa', 'Cohorte, tropa militar', 'Una cohorte o destacamento militar romano, compuesto típicamente por unos 600 soldados bajo el mando de un tribuno (χιλίαρχος). En el NT siempre tiene este sentido técnico militar romano, sin las acepciones clásicas de espirales o cuerdas. Aparece en los relatos de la Pasión para los soldados que arrestan y escarnecen a Jesús (Mt 27:27; Mc 15:16; Jn 18:3, 12) y en Hechos para unidades de guarnición con nombre, como la Cohorte Italiana y la Cohorte Augusta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76594, 'spa', 'El sembrador (sustantivado)', 'Forma participial sustantivada que significa ''el sembrador'', figura que se convierte casi en titulo en las parabolas de Jesus. En Mateo 13:3 el sembrador sale a sembrar y en 13:37 Jesus lo identifica como ''el Hijo del Hombre''. La traduccion uniforme (espanol ''sembrador'') muestra como el participio se convirtio en designacion de personaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76595, 'spa', 'Ser sembrado, lo sembrado', 'La voz pasiva indicando lo que ha sido sembrado, prominente en la interpretacion de la parabola donde ''lo sembrado en pedregales'' representa un tipo de oyente (Mateo 13:20). Pablo en 1 Corintios 15:42-44 emplea esta forma repetidamente: ''se siembra en corrupcion, se resucita en incorrupcion''. El espanol ''es sembrado/a'' captura este matiz gramatical.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76598, 'spa', 'Sembrar, plantar', 'El sentido activo de esparcir o plantar semilla, abarcando tanto la agricultura literal (Mateo 6:26, ''no siembran ni cosechan'') como la siembra figurada del evangelio o de la justicia. El espanol ''sembrar'' refleja fielmente el significado agricola base. La parabola de Jesus comienza con este acto: ''salio el sembrador a sembrar'' (Mateo 13:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76619, 'spa', 'Descendencia, posteridad o progenie — el sentido dominante en el NT', 'Descendencia, posteridad o progenie — el sentido dominante en el NT. Central en la teología del pacto abrahámico: ''tu simiente'' (Jn 8:33; Rom 9:7-8; Gál 3:29) y el linaje davídico (Rom 1:3; 2 Tim 2:8). Pablo basa su argumento singular/plural en Gálatas 3:16 enteramente en esta palabra. También aparece en la parábola del trigo y la cizaña (Mat 13:24-38), donde ''la buena semilla'' representa a los hijos del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76621, 'spa', 'Semillas literales y físicas en contextos agrícolas o botánicos', 'Semillas literales y físicas en contextos agrícolas o botánicos. La semilla de mostaza (Mat 13:32; Mar 4:31) es el ejemplo clásico: la más pequeña de las semillas que crece hasta ser un gran arbusto. Pablo usa el plural σπέρμασιν en 1 Cor 15:38 para distintos tipos de grano, y contrasta deliberadamente el plural ''semillas'' con el singular ''simiente'' en Gál 3:16. El español ''semillas'' marca el sentido concreto y botánico del término.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76625, 'spa', 'Apresurarse, darse prisa', 'Apresurarse, darse prisa o moverse con rapidez anhelante hacia un destino o una acción, transmitiendo tanto celeridad física como urgencia intencional. Los pastores se apresuraron a Belén (Luke 2:16), Zaqueo bajó de prisa de su árbol por mandato de Jesús (Luke 19:5-6), Pablo se apresuraba hacia Jerusalén para Pentecostés (Acts 20:16) y el Señor instó a Pablo a salir de Jerusalén rápidamente (Acts 22:18). En 2 Peter 3:12, el mismo verbo adquiere dimensión escatológica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76630, 'spa', 'Cueva, guarida', 'Cueva, guarida o cavidad natural en la roca, usada como refugio, escondite o sepultura. La cita de Jeremías 7:11 — ''cueva de ladrones'' (Mat 21:13; Mar 11:17; Luc 19:46) — evoca un escondite de bandidos. Juan 11:38 lo aplica a la tumba de Lázaro, Hebreos 11:38 a refugios de santos perseguidos, y Apocalipsis 6:15 a escondrijos ante el juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76635, 'spa', 'Ser movido a compasión', 'Ser movido a compasión: Sentir compasión profunda y visceral que impulsa a la acción misericordiosa — usado de Jesús al ver multitudes sin pastor (Mt 9:36), las multitudes hambrientas (Mt 14:14; Mc 8:2), los enfermos (Mt 20:34), y en parábolas del rey perdonador (Mt 18:27), el buen samaritano (Lc 10:33) y el padre del pródigo (Lc 15:20). El español ''compadecerse'' capta la dimensión visceral y activa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76639, 'spa', 'Afecto profundo y tierna compasión, entendida como surgida de lo más íntimo del ', 'Afecto profundo y tierna compasión, entendida como surgida de lo más íntimo del ser. Esta extensión metafórica domina el NT: Pablo apela a los filipenses ''por cualquier σπλάγχνα y compasión'' (Fil 2:1), confiesa anhelarlos ''con las σπλάγχνα de Cristo Jesús'' (Fil 1:8) y dice a los corintios que sus propias entrañas están abiertas de par en par para ellos (2 Co 6:12). Filemón es elogiado porque las entrañas de los santos han sido reconfortadas por medio de él (Flm 7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76642, 'spa', 'Los órganos internos literales o vísceras del cuerpo', 'Los órganos internos literales o vísceras del cuerpo. Este significado más antiguo y anatómico aparece únicamente en Hechos 1:18, donde Judas cayó de cabeza, su cuerpo se reventó y todas sus entrañas se derramaron. La cruda fisicalidad de este único uso literal contrasta fuertemente con el tierno sentido metafórico que predomina en las epístolas. El español ''entrañas'' y el francés ''entrailles'' son ambiguos de la misma manera.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76643, 'spa', 'Esponja', 'Las traducciones son idénticas en todas las lenguas: español «esponja», francés «éponge», alemán «Schwamm». Esto refleja un objeto concreto y universalmente reconocido. Los tres relatos evangélicos coinciden en este detalle: una esponja empapada en vinagre ofrecida a Cristo moribundo, cumpliendo el Salmo 69:21 mientras brinda un alivio pasajero o quizá una última afrenta en el Gólgota.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76644, 'spa', 'Ceniza ritual', 'Uniforme en todos los idiomas: espanol ''ceniza'', frances ''cendre'', aleman ''Asche''. El doble uso neotestamentario muestra tanto la funcion metaforica (arrepentimiento en cilicio y ceniza) como la ceremonial (ceniza de becerra para purificacion). La declaracion contrafactual de Jesus presupone que sus oyentes conocen esta practica penitencial: la ceniza como expresion fisica de quebranto y reconocimiento de la mortalidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76646, 'spa', 'Campos sembrados', 'Las traducciones varian ligeramente pero convergen en tierras cultivadas: espanol ''sembrados'', frances ''champ de ble'', aleman ''Saatfeld''. La unanimidad de los sinopticos en este escenario refleja un recuerdo autentico: Jesus y sus discipulos caminando entre espigas en sabado, lo cual desencadena un conflicto que revela su autoridad sobre la ley sabatica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76647, 'spa', 'Semilla para siembra', 'Semilla destinada a la siembra: el grano que el agricultor esparce sobre la tierra, usado literal y figuradamente. En Marcos 4:26-27, un hombre echa σπόρος en la tierra y duerme mientras crece misteriosamente; en Lucas 8:11, Jesús identifica la semilla como la palabra de Dios. Pablo emplea la misma imagen en 2 Cor 9:10 para la provisión divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76648, 'spa', 'Ser diligente, poner todo empeño o apresurarse con ahínco hacia una meta, combin', 'Ser diligente, poner todo empeño o apresurarse con ahínco hacia una meta, combinando celo interior con urgencia exterior. Se usa para el esfuerzo moral y espiritual (Ef 4:3, mantener la unidad; 2 Ti 2:15, presentarse aprobado; 2 P 1:10, confirmar la vocación; 2 P 3:14, ser hallado en paz; He 4:11, entrar en el reposo de Dios), para la solicitud caritativa (Gá 2:10, acordarse de los pobres; 1 Ts 2:17, anhelando ver a los hermanos) y para la urgencia práctica de viajes y visitas (2 Ti 4:9, 21; Tit 3:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76655, 'spa', 'Fervoroso y diligente', 'Las traducciones se agrupan en torno a ''fervoroso/celoso/diligente'': espanol ''diligente'', frances ''zele'', aleman ''eifrig''. Las formas comparativas (''mas diligente'') reflejan la retorica de Pablo en 2 Co 8:22, donde elogia a un hermano como ''aun mas fervoroso''. No se trata de mera actividad, sino de un compromiso genuino del corazon, el tipo de celo que demuestra autentica preocupacion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76657, 'spa', 'Con diligencia fervorosa', 'Los idiomas convergen: espanol ''diligentemente'', frances ''avec empressement'', aleman ''eifrig''. Los tres contextos neotestamentarios comparten el tema de ir mas alla del esfuerzo minimo: ancianos que suplican con urgencia, Onesiforo que busca sin descanso, Pablo que encarga un apoyo cabal. Es el adverbio de la accion entregada, donde el fervor se manifiesta en hechos concretos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76658, 'spa', 'Diligencia', 'Diligencia: Diligencia, fervor o celo ardiente — una disposición interior de compromiso entusiasta y enérgico. Pablo lo encomia como virtud junto al amor y la fe (Ro 12:8, 11; 2 Co 8:7-8), alaba la solicitud ferviente de los corintios (2 Co 7:11-12) y exhorta a los creyentes a ''poner toda diligencia'' (2 Pe 1:5; Jud 1:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76659, 'spa', 'Prisa', 'Prisa: Prisa o urgencia, describiendo movimiento físico veloz impulsado por circunstancias apremiantes. Salomé regresa ante Herodes ''con prisa'' tras pedir la cabeza de Juan (Mc 6:25), y María viaja ''con prisa'' a visitar a Elisabet al escuchar el anuncio del ángel (Lc 1:39). La frase preposicional μετὰ σπουδῆς distingue este sentido temporal-cinético del significado disposicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76662, 'spa', 'Canasta grande', 'Canasta o espuerta grande (σπυρίς), claramente mayor que el κόφινος usado en la alimentación de los cinco mil. Las cinco apariciones neotestamentarias se concentran en dos episodios: la alimentación de los cuatro mil, donde se recogieron siete espuertas de sobras (Mt 15:37; Mc 8:8; recordado en Mt 16:10; Mc 8:20), y la dramática huida de Pablo de Damasco en una canasta descolgada por la muralla (Hch 9:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76663, 'spa', 'Unidad de distancia', 'Medida de longitud equivalente a unos 185 metros (aproximadamente un octavo de milla romana), empleada para calcular distancias por tierra o mar. Los Evangelios la usan con precisión geográfica: Betania dista quince estadios de Jerusalén (Juan 11:18), Emaús sesenta (Lucas 24:13). En Apocalipsis 14:20, el flujo apocalíptico de sangre se extiende 1.600 estadios, una hipérbole sobrecogedora de distancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76664, 'spa', 'Arena o pista deportiva', 'El recinto físico —la pista de carreras o arena (de un estadio de largo)— donde se celebraban carreras a pie y otras competencias atléticas. Pablo emplea esta imagen concreta en 1 Corintios 9:24: ''los que corren en el estadio, todos corren, pero uno solo recibe el premio''. Aquí la palabra pasa de medida abstracta al entorno construido de la competición.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76666, 'spa', 'Disensión, disputa', 'Desacuerdo intenso o disputa facciosa dentro de un grupo, especialmente sobre asuntos religiosos o doctrinales. Su emparejamiento con ζήτησις («debate») en Hechos 15:2 resalta el carácter verbal y argumentativo. En Hechos 23:7 el choque entre fariseos y saduceos sobre la resurrección se convierte en una στάσις tan feroz que el tribuno debe intervenir (Hch 23:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76667, 'spa', 'Insurrección, revuelta', 'Levantamiento violento, motín o insurrección contra la autoridad civil. Lucas 23:19 y 23:25 lo emplean para la insurrección de Jerusalén por la cual Barrabás fue encarcelado; Marcos 15:7 nombra a sus compañeros insurgentes. Hechos 19:40 advierte que el motín de los plateros de Éfeso podría ser acusado como στάσις, una categoría jurídica romana de gravedad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76671, 'spa', 'Posición, vigencia', 'Estado de estar en pie, tener una posición establecida o un estatus reconocido — el significado más literal derivado de ἵστημι. En Hebreos 9:8, el autor argumenta que mientras el primer tabernáculo aún «tiene vigencia» (ἐχούσης στάσιν), el camino al lugar santísimo permanece cerrado. Este matiz espacial y jurídico se distingue claramente de los sentidos de conflicto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76673, 'spa', 'cruz — La cruz de madera como instrumento de ejecución romana en la que Jesús fu', 'cruz — La cruz de madera como instrumento de ejecución romana en la que Jesús fue crucificado. Aparece en los relatos de la Pasión como el objeto físico cargado por Simón de Cirene (Mt 27:32; Mc 15:21; Lc 23:26), sobre el cual Jesús fue clavado (Jn 19:17-19, 25, 31), y desde el cual los burladores lo desafiaban a descender (Mt 27:40, 42; Mc 15:30, 32). Metafóricamente, Jesús la transforma en llamado al discipulado radical y a la abnegación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76675, 'spa', 'Ejecutar clavando o atando a una cruz, y por extensión, destruir el poder de alg', 'Ejecutar clavando o atando a una cruz, y por extensión, destruir el poder de algo mediante la identificación con esa muerte. Usado literalmente de la crucifixión de Jesús en los cuatro relatos de la Pasión (Mat 27:22-38; Mar 15:13-27; Luc 23:21-33; Jn 19:6-23) y en la predicación apostólica primitiva que proclama al ''Cristo crucificado'' (Hch 2:36; 1 Cor 1:23; 2:2). Pablo extiende el verbo figuradamente: los creyentes han ''crucificado la carne con sus pasiones'' (Gál 5:24) y el mundo queda crucificado para el apóstol por medio de la cruz (Gál 6:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76696, 'spa', 'Racimo de uvas', 'Traducciones uniformes: espanol ''uva/uvas'', frances ''raisin'', aleman ''Trauben''. El uso proverbial de Jesus (se conoce la planta por su fruto) presupone que las uvas crecen en vides, no en espinos: sabiduria agricola evidente que se convierte en metafora espiritual. La cosecha apocaliptica de Apocalipsis extiende la imagen: la humanidad como vina, los racimos recogidos para el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76697, 'spa', 'Espiga de cereal', 'La espiga o cabeza del cereal, el racimo de granos en la punta del tallo de trigo o cebada. En los relatos de la controversia sabática (Mt 12:1; Mc 2:23; Lc 6:1) los discípulos arrancan espigas para comer, acción permitida por Deuteronomio 23:25 pero impugnada por los fariseos. Marcos 4:28 describe el ciclo agrícola completo: del brote a la espiga y al grano maduro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76699, 'spa', 'Techo, tejado', 'Uniformidad entre idiomas: inglés ''roof'', español ''techo'', francés ''toit'', alemán ''Dach''. La humildad del centurión se expresa espacialmente: «No soy digno de que entres bajo mi techo», reconociendo un límite de santidad y condición. El relato de Marcos sobre el paralítico bajado a través del techo revela tanto la arquitectura antigua (techos planos y accesibles) como una fe desesperada, dispuesta a abrir brecha en las barreras físicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76700, 'spa', 'Soportar con paciencia', 'Soportar, aguantar, sobrellevar con paciencia; originalmente ''cubrir para impedir el paso del agua'', de ahí contener o resistir la presión. En 1 Corintios 9:12 Pablo todo lo soporta por amor al evangelio. En el capítulo del amor (1 Corintios 13:7), el amor «todo lo soporta», cubriendo y absorbiendo lo que de otro modo quebraría. En 1 Tesalonicenses 3:1, 5 expresa no poder contenerse más.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76701, 'spa', 'Estéril, infecunda', 'Estéril, incapaz de tener hijos; se dice de mujeres cuya infecundidad se convierte en escenario de intervención divina o argumento teológico. La esterilidad de Elisabet (Lc 1:7, 36) prepara el nacimiento milagroso del Bautista; la de Sara (Heb 11:11) demuestra el poder de la fe. Lucas 23:29 invierte las expectativas llamando ''bienaventuradas'' a las estériles ante el juicio venidero. Gálatas 4:27 aplica la imagen alegóricamente al nuevo pacto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76705, 'spa', 'Gemir, suspirar con angustia', 'Gemir o suspirar profundamente por angustia, sufrimiento o anhelo intenso — una expresión involuntaria y corporal de dolor interior o deseo vehemente. El στενάξας de Jesús en Marcos 7:34 revela un dolor empático antes del milagro de sanidad; en Romanos 8:23 y 2 Corintios 5:2-4, los creyentes gimen bajo la tensión entre el sufrimiento mortal presente y la glorificación futura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76710, 'spa', 'Estrecho, angosto', 'Coincidencia entre lenguas: inglés ''narrow'', español ''estrecha'', francés ''étroit'', alemán con transliteraciones del griego (στενή). Los tres usos en Mateo 7:13-14 y Lucas 13:24 establecen una imagen coherente: la puerta y el camino hacia la vida son estrechos, no espaciosos. Esta estrechez no es restricción arbitraria, sino la realidad de que el camino del discipulado es enfocado, exigente y transitado por pocos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76711, 'spa', 'Angustia y constricción', 'Las traducciones reflejan el doble sentido: inglés ''restricted/crushed'', español ''angustiados'', francés ''être à l''étroit'' (estar apretado), alemán ''Bedrängnis'' (aflicción). Los usos paulinos captan ambas dimensiones: presiones externas (4:8) y constricción emocional interna (6:12). La paradoja de 4:8 —«atribulados pero no aplastados»— juega con el rango semántico del verbo: la presión existe, pero no llega a destruir.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76712, 'spa', 'Angustia o aprieto', 'Angustia, aflicción extrema, aprieto; literalmente una constricción de espacio que no deja escapatoria. Derivado de στενός (''estrecho'') y χώρα (''espacio''), describe la sensación de ser estrujado por todos lados. Se empareja frecuentemente con θλῖψις (''tribulación''): Romanos 2:9 advierte de ''tribulación y angustia'' para los que obran el mal, mientras Romanos 8:35 pregunta si tales fuerzas pueden separarnos del amor de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76713, 'spa', 'Firme, sólido', 'Firme, sólido, duro; en sentido figurado, constante e inquebrantable. En el uso clásico se opone a hueco (κοῖλον), blando (μαλθακός) o vacío (κενόν), describiendo aquello que resiste la presión. En Heb 5:12, 14 caracteriza el «alimento sólido», enseñanza avanzada para los maduros. En 2 Tim 2:19 el «fundamento firme» de Dios permanece inmutable ante la apostasía. En 1 Pe 5:9, los creyentes deben mantenerse firmes en la fe frente al adversario.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76714, 'spa', 'Fortalecer, afianzar', 'Las lenguas varían levemente: inglés ''strengthened'', español ''fortaleció/fueron fortalecidas'', francés ''affermir'' (hacer firme). La narrativa de Hechos transita de lo físico (los tobillos del cojo fortalecidos) a lo espiritual (iglesias fortalecidas en la fe). Ambos sentidos comparten la idea central: lo que era débil, inestable o quebrantado se vuelve sólido, firme y capaz de sostenerse en pie.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76716, 'spa', 'Nombre propio', 'Como nombre propio, las traducciones son estables: inglés ''Stephanas'', español ''Estéfanas'', francés ''Stéphanas'', alemán ''Stephanas''. La forma genitiva constante («de Estéfanas») en las tres referencias refleja el patrón paulino de mencionar a este fiel líder de familia y sus compañeros, destacando su servicio y el vínculo personal de Pablo con ellos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76717, 'spa', 'Corona, guirnalda', 'Corona, guirnalda: una guirnalda tejida o circulo colocado sobre la cabeza como senal de victoria, honor o dignidad real, abarcando tanto la corona fisica de espinas puesta sobre Jesus en burla (Mt 27:29; Mc 15:17; Jn 19:2, 5) como la corona metaforica de recompensa por la fidelidad. Pablo habla de la ''corona incorruptible'' de la autodisciplina atletica (1 Co 9:25), ''la corona de justicia'' en el retorno de Cristo (2 Ti 4:8), y sus convertidos como su ''gozo y corona'' (Fil 4:1; 1 Ts 2:19). Santiago 1:12 y Apocalipsis 2:10 prometen ''la corona de vida''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76719, 'spa', 'Esteban (nombre propio)', 'Nombre propio Esteban (Στέφανος), que designa al primer mártir cristiano. Creyente judío helenista elegido como uno de los siete diáconos (Hechos 6:5), estaba ''lleno de gracia y de poder'' (Hechos 6:8) y debatía con opositores de diversas sinagogas (Hechos 6:9). Su discurso ante el tribunal (Hechos 7) y su muerte por lapidación — durante la cual tuvo una visión del Hijo del Hombre y oró por sus perseguidores (Hechos 7:55-60) — marcaron un hito en la historia de la iglesia primitiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76721, 'spa', 'Coronar con honor', 'Los tres usos neotestamentarios abarcan la metáfora atlética (la corona del vencedor), la teología (la dignidad destinada a la humanidad) y la cristología (Jesús coronado mediante el sufrimiento). En cada contexto se confiere honor: ya sea el laurel ganado por disciplina o la gloria y honra restauradas a la humanidad por medio de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76722, 'spa', 'Pecho o torso', 'El pecho o torso, la superficie frontal del cuerpo superior. En el NT aparece en tres contextos: el golpe penitente o de duelo en el pecho (Lc 18:13, el publicano; Lc 23:48, las multitudes afligidas), la cercanía física íntima (Jn 13:25; 21:20, el discípulo amado reclinado sobre el pecho de Jesús) y la vestimenta ceremonial (Ap 15:6, ángeles con bandas de oro cruzadas sobre el pecho).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76723, 'spa', 'Mantenerse firme, perseverar, permanecer constante en la fe, la convicción o el ', 'Mantenerse firme, perseverar, permanecer constante en la fe, la convicción o el compromiso — el sentido paulino dominante. Formado a partir del tema perfectivo de ἵστημι, στήκω transmite intrínsecamente una postura asentada y establecida. Pablo lo emplea como grito de guerra: ''Estad firmes en un mismo espíritu'' (Fil 1:27), ''Estad firmes en la fe; sed valientes'' (1 Co 16:13), ''Estad firmes en la libertad'' que Cristo ganó (Gá 5:1). En Jn 8:44 se usa negativamente: el diablo ''no se mantuvo en la verdad''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76726, 'spa', 'Estar de pie físicamente, encontrarse en posición erguida — un sentido literal y', 'Estar de pie físicamente, encontrarse en posición erguida — un sentido literal y posicional. En Marcos 3:31, la madre y los hermanos de Jesús estaban ''de pie'' (στήκοντες) afuera, y en Marcos 11:25 Jesús instruye: ''cuando estéis de pie (στήκετε) orando, perdonad''. El español ''estando de pie'' y ''estéis de pie'' conservan el registro claramente físico. Aunque la postura de estar de pie para orar podría sugerir un matiz espiritual, el contexto de Marcos trata estas apariciones como posicionales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76730, 'spa', 'Fortalecer o establecer espiritualmente', 'Fortalecer o establecer espiritualmente: el uso dominante en el NT, referido a fortalecer a los creyentes en fe, determinación o firmeza moral. Jesús dice a Pedro ''confirma a tus hermanos'' (Lucas 22:32); Pablo ora para que Dios ''afirme vuestros corazones'' (1 Tesalonicenses 3:13; 2 Tesalonicenses 2:17; 3:3) y que el evangelio ''confirme'' a los romanos (Romanos 16:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76733, 'spa', 'Fijar firmemente en un lugar físico o metafórico', 'Fijar firmemente en un lugar físico o metafórico: un sentido concreto de establecer algo de manera inamovible. Jesús ''afirmó su rostro'' hacia Jerusalén con determinación inquebrantable (Lucas 9:51), y Abraham le dice al rico que un ''gran abismo ha sido fijado'' entre ellos (Lucas 16:26). El énfasis recae en la permanencia e inmovilidad de lo establecido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76736, 'spa', 'Ser establecido o fortalecido por la acción de otro (voz pasiva)', 'Ser establecido o fortalecido por la acción de otro (voz pasiva). Pablo desea impartir un don espiritual para que los romanos sean ''confirmados'' (Romanos 1:11), y Pedro escribe a quienes ya están ''establecidos en la verdad'' (2 Pedro 1:12). Este sentido marca el lado receptivo de la dinámica de fortalecimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76743, 'spa', 'Pórtico, columnata', 'Columnata techada o pórtico; pasadizo cubierto sostenido por pilares, característico de la arquitectura pública antigua. En Jn 5:2 describe los cinco pórticos que rodeaban el estanque de Betesda. El Pórtico de Salomón (στοὰ Σολομῶντος) en el monte del templo es el escenario de la enseñanza de Jesús en la Fiesta de la Dedicación (Jn 10:23) y de las reuniones de los primeros cristianos (Hch 3:11; 5:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76745, 'spa', 'Elementos fundamentales', 'Los componentes básicos, principios elementales o constituyentes fundamentales del mundo. Este sentido abarca usos neotestamentarios superpuestos: los principios rudimentarios de la instrucción religiosa, el ''abecé'' que los creyentes maduros ya deberían haber superado (Hebreos 5:12); y los ''elementos del mundo'', es decir, los principios ordenadores básicos (ya sean regulaciones de la Torá, poderes cósmicos, o ambos) que antes esclavizaban a los creyentes antes de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76748, 'spa', 'Andar conforme a norma', 'Caminar en conformidad con una regla, norma o ejemplo, conduciendo la vida de manera ordenada y alineada con un principio rector. Desde su origen militar de marchar en formación, el uso neotestamentario es enteramente metafórico: Pablo exhorta a caminar por el Espíritu (Gá 5:25), a seguir las pisadas de fe de Abraham (Ro 4:12) y a mantenerse firmes en la misma regla (Fil 3:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76749, 'spa', 'Vestidura, ropaje largo', 'Vestidura exterior larga y formal, que típicamente significa honor, autoridad o pureza celestial. A diferencia del simple ἱμάτιον (manto) o χιτών (túnica), la στολή es un ropaje ceremonial asociado con la dignidad. Los escribas disfrutan ostentarlas (Mr 12:38; Lc 20:46), el padre ordena la mejor para el pródigo que regresa (Lc 15:22), y los santos resucitados son revestidos con vestiduras blancas (Ap 6:11; 7:9, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76754, 'spa', 'Boca, abertura oral', 'La boca como organo fisico y, por metonimia, el habla o testimonio que de ella emana. Jesus ensena que la boca revela el corazon (Mateo 12:34; 15:11), y el principio legal de ''dos o tres testigos'' invoca στόμα para testimonio autorizado (Mateo 18:16). En Apocalipsis, una espada sale de la boca de Cristo (1:16; 19:15), fusionando organo y palabra divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76763, 'spa', 'Ejército, fuerza militar', 'Cuerpo organizado de soldados, ejército o destacamento militar, ya sea desplegado en batalla, para hacer cumplir la ley o como escolta. En Mateo 22:7, los «ejércitos» del rey ejecutan juicio en la parábola; en Hechos 23:10 y 23:27, un destacamento romano rescata a Pablo de la violencia, mostrando el rango del término desde fuerzas masivas hasta pequeñas unidades tácticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (76769, 'spa', 'Guerrear metafóricamente', 'Hacer guerra o llevar a cabo una campaña en sentido figurado o espiritual, describiendo la batalla interior de los deseos o la lucha de la vida cristiana. Santiago 4:1 pregunta qué causa las guerras entre creyentes y responde: los placeres que ''combaten'' (στρατεύονται) en vuestros miembros. Pablo despliega la misma metáfora en 2 Corintios 10:3 y 1 Timoteo 1:18 (''milita la buena milicia''), mientras que 1 Pedro 2:11 exhorta a abstenerse de los deseos carnales que batallan contra el alma.');